import { EChart, type EChartSetup } from "@/components/ui/echart"
import * as echarts from "echarts"
import type { EChartsOption } from "echarts"

// Adapted from the Apache ECharts example "Transition of Parliament and Pie Chart" (Apache-2.0):
// https://echarts.apache.org/examples/en/editor.html?c=pie-parliament-transition
const setup: EChartSetup = ({ myChart, setInterval }) => {
  let option!: EChartsOption
  const data = [
    { value: 800, name: 'A' },
    { value: 635, name: 'B' },
    { value: 580, name: 'C' },
    { value: 484, name: 'D' },
    { value: 300, name: 'E' },
    { value: 200, name: 'F' }
  ];

  const defaultPalette = [
    '#5070dd',
    '#b6d634',
    '#505372',
    '#ff994d',
    '#0ca8df',
    '#ffd10a',
    '#fb628b',
    '#785db0',
    '#3fbe95'
  ];

  const radius = ['30%', '80%'];

  const pieOption: echarts.EChartsOption = {
    series: [
      {
        type: 'pie',
        id: 'distribution',
        radius: radius,
        label: {
          show: false
        },
        universalTransition: true,
        animationDurationUpdate: 1000,
        data: data
      }
    ]
  };

  const parliamentOption = (function () {
    let sum = data.reduce(function (sum, cur) {
      return sum + cur.value;
    }, 0);

    let angles: number[] = [];
    let startAngle = -Math.PI / 2;
    let curAngle = startAngle;
    data.forEach(function (item) {
      angles.push(curAngle);
      curAngle += (item.value / sum) * Math.PI * 2;
    });
    angles.push(startAngle + Math.PI * 2);
    function parliamentLayout(
      startAngle: number,
      endAngle: number,
      totalAngle: number,
      r0: number,
      r1: number,
      size: number
    ) {
      let rowsCount = Math.ceil((r1 - r0) / size);
      let points = [];

      let r = r0;
      for (let i = 0; i < rowsCount; i++) {
        // Recalculate size
        let totalRingSeatsNumber = Math.round((totalAngle * r) / size);
        let newSize = (totalAngle * r) / totalRingSeatsNumber;
        for (
          let k = Math.floor((startAngle * r) / newSize) * newSize;
          k < Math.floor((endAngle * r) / newSize) * newSize - 1e-6;
          k += newSize
        ) {
          let angle = k / r;
          let x = Math.cos(angle) * r;
          let y = Math.sin(angle) * r;
          points.push([x, y]);
        }

        r += size;
      }

      return points;
    }
    return {
      series: {
        type: 'custom',
        id: 'distribution',
        data: data,
        coordinateSystem: undefined,
        universalTransition: true,
        animationDurationUpdate: 1000,
        renderItem: function (params, api) {
          var idx = params.dataIndex;
          var viewSize = Math.min(api.getWidth(), api.getHeight());
          var r0 = ((parseFloat(radius[0]) / 100) * viewSize) / 2;
          var r1 = ((parseFloat(radius[1]) / 100) * viewSize) / 2;
          var cx = api.getWidth() * 0.5;
          var cy = api.getHeight() * 0.5;
          var size = viewSize / 50;

          var points = parliamentLayout(
            angles[idx],
            angles[idx + 1],
            Math.PI * 2,
            r0,
            r1,
            size + 3
          );

          return {
            type: 'group',
            children: points.map(function (pt) {
              return {
                type: 'circle',
                autoBatch: true,
                shape: {
                  cx: cx + pt[0],
                  cy: cy + pt[1],
                  r: size / 2
                },
                style: {
                  fill: defaultPalette[idx % defaultPalette.length]
                }
              };
            })
          };
        }
      }
    } as echarts.EChartsOption;
  })();

  let currentOption = (option = pieOption);

  setInterval(function () {
    currentOption = currentOption === pieOption ? parliamentOption : pieOption;
    myChart.setOption(currentOption);
  }, 2000);
  return option
}

export function EchartsPieParliamentTransition() {
  return <EChart setup={setup} />
}
